--
-- Name: level_test_attempt_events; Type: TABLE; Schema: public; Owner: app
--

CREATE TABLE public.level_test_attempt_events (
    account_id uuid NOT NULL,
    event_id uuid NOT NULL,
    attempt_id uuid NOT NULL,
    revision integer NOT NULL,
    event_hash text NOT NULL,
    ack_json jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT level_test_attempt_events_ack_json_check CHECK ((jsonb_typeof(ack_json) = 'object'::text)),
    CONSTRAINT level_test_attempt_events_event_hash_check CHECK ((event_hash ~ '^[a-f0-9]{64}$'::text)),
    CONSTRAINT level_test_attempt_events_revision_check CHECK ((revision > 1))
);


