--
-- Name: level_test_attempt_snapshots; Type: TABLE; Schema: public; Owner: app
--

CREATE TABLE public.level_test_attempt_snapshots (
    account_id uuid NOT NULL,
    content_id text NOT NULL,
    content_hash text NOT NULL,
    content_json jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT level_test_attempt_snapshots_check CHECK ((content_id = ('sha256:'::text || content_hash))),
    CONSTRAINT level_test_attempt_snapshots_content_hash_check CHECK ((content_hash ~ '^[a-f0-9]{64}$'::text))
);


ALTER TABLE public.level_test_attempt_snapshots OWNER TO app;

--
-- Name: level_test_attempts; Type: TABLE; Schema: public; Owner: app
--

CREATE TABLE public.level_test_attempts (
    account_id uuid NOT NULL,
    attempt_id uuid NOT NULL,
    exam_id text NOT NULL,
    state text NOT NULL,
    "position" integer NOT NULL,
    revision integer NOT NULL,
    started_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    completed_at timestamp with time zone,
    answers jsonb NOT NULL,
    result jsonb,
    attempt_json jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT level_test_attempts_answers_check CHECK ((jsonb_typeof(answers) = 'array'::text)),
    CONSTRAINT level_test_attempts_attempt_json_check CHECK ((jsonb_typeof(attempt_json) = 'object'::text)),
    CONSTRAINT level_test_attempts_check CHECK ((updated_at >= started_at)),
    CONSTRAINT level_test_attempts_check1 CHECK ((((state = 'in_progress'::text) AND (completed_at IS NULL) AND (result IS NULL)) OR ((state = 'completed'::text) AND (completed_at IS NOT NULL) AND (completed_at >= started_at) AND (result IS NOT NULL)))),
    CONSTRAINT level_test_attempts_position_check CHECK ((("position" >= 0) AND ("position" <= 1000))),
    CONSTRAINT level_test_attempts_revision_check CHECK ((revision > 0)),
    CONSTRAINT level_test_attempts_state_check CHECK ((state = ANY (ARRAY['in_progress'::text, 'completed'::text])))
);


ALTER TABLE public.level_test_attempts OWNER TO app;

