COPY public.level_test_attempt_snapshots (account_id, content_id, content_hash, content_json, created_at) FROM stdin;
a0000000-0000-4000-8000-00000000e2e1	sha256:7b53d413b481ad2c4b9b24f8febb88eb86e2cf65bbd386c08251903839789237	7b53d413b481ad2c4b9b24f8febb88eb86e2cf65bbd386c08251903839789237	{"items": [{"id": "en-foundations-u3-present-e3", "kind": "order", "prompt": "Say you do not eat meat.", "unitID": "en-foundations-u3", "answers": ["We don't eat meat"], "explain": "don't + base verb: We don't eat.", "options": [], "section": "recognition"}, {"id": "en-foundations-u4-there-is-e1", "kind": "choice", "prompt": "___ a pharmacy near here?", "unitID": "en-foundations-u4", "answers": ["Is there"], "explain": "Singular questions: Is there …?", "options": ["Is there", "Are there", "There is", "Has"], "section": "recognition"}, {"id": "en-foundations-meals-restaurant-e3", "kind": "order", "prompt": "Order the soup.", "unitID": "en-foundations-meals", "answers": ["Ill have the soup please"], "explain": "I'll have + dish + please.", "options": [], "section": "recognition"}, {"id": "en-foundations-days-calendar-e1", "kind": "choice", "prompt": "The course starts ___ September.", "unitID": "en-foundations-days", "answers": ["in"], "explain": "Months take in: in September.", "options": ["in", "on", "at", "to"], "section": "recognition"}, {"id": "en-foundations-u4-can-e2", "kind": "gap", "prompt": "I ___ swim, but I can't dive.", "unitID": "en-foundations-u4", "answers": ["can"], "explain": "can never takes -s and stays with the verb.", "options": [], "section": "recognition"}, {"id": "en-foundations-town-places-e3", "kind": "order", "prompt": "Ask about a bank.", "unitID": "en-foundations-town", "answers": ["Is there a bank near here"], "explain": "Is there + a + place?", "options": [], "section": "recognition"}, {"id": "en-foundations-days-free-time-e3", "kind": "order", "prompt": "Ask about free time.", "unitID": "en-foundations-days", "answers": ["What do you do in your free time"], "explain": "Question word + do + you + verb.", "options": [], "section": "recognition"}, {"id": "en-foundations-u1-questions-e1", "kind": "choice", "prompt": "___ you tired?", "unitID": "en-foundations-u1", "answers": ["Are"], "explain": "With you, the question starts with Are.", "options": ["Are", "Is", "Am", "Be"], "section": "recognition"}, {"id": "en-foundations-town-places-e2", "kind": "gap", "prompt": "There ___ a library in my town. (negative)", "unitID": "en-foundations-town", "answers": ["isn't", "is not"], "explain": "there isn't a…", "options": [], "section": "recognition"}, {"id": "en-foundations-now-continuous-e2", "kind": "gap", "prompt": "Look! It ___ (rain).", "unitID": "en-foundations-now", "answers": ["is raining", "'s raining", "is raing"], "explain": "It is raining — weather takes it.", "options": [], "section": "recognition"}, {"id": "en-foundations-u1-to-be-e1", "kind": "choice", "prompt": "She ___ a doctor.", "unitID": "en-foundations-u1", "answers": ["is"], "explain": "With he, she and it, to be becomes is.", "options": ["is", "are", "am", "be"], "section": "recognition"}, {"id": "checkpoint-en-a1-q12", "kind": "choice", "prompt": "My mother's mother is my ___.", "answers": ["grandmother"], "explain": "mother's mother = grandmother.", "options": ["grandmother", "sister", "aunt", "cousin"], "section": "recognition"}, {"id": "en-listen-bus-stop-chat-q3#r", "kind": "choice", "prompt": "Who is visiting Ben?", "unitID": "en-foundations-out", "answers": ["His sister"], "explain": "His sister is visiting, so they'll walk by the river.", "options": ["His sister", "His mother", "A neighbour", "Nobody"], "section": "reading", "passageId": "en-listen-bus-stop-chat"}, {"id": "en-listen-bus-stop-chat-q2#r", "kind": "written", "prompt": "What are the woman's plans for the weekend?", "unitID": "en-foundations-out", "answers": ["tea and a book", "tea", "a book"], "explain": "Her plans are tea and a book.", "options": [], "section": "reading", "passageId": "en-listen-bus-stop-chat"}, {"id": "en-listen-bus-stop-chat-q1#r", "kind": "choice", "prompt": "How does Ben open the conversation?", "unitID": "en-foundations-out", "answers": ["About the cold"], "explain": "'Cold today, isn't it?' — the weather opener.", "options": ["About the cold", "About the bus", "About the river", "About tea"], "section": "reading", "passageId": "en-listen-bus-stop-chat"}, {"id": "en-listen-lost-umbrella-q2#r", "kind": "choice", "prompt": "What colour is the umbrella next to the chair?", "unitID": "en-foundations-u2", "answers": ["Blue"], "explain": "It is a big blue umbrella.", "options": ["Blue", "Green", "Black", "Red"], "section": "reading", "passageId": "en-listen-lost-umbrella"}, {"id": "en-listen-lost-umbrella-q1#r", "kind": "choice", "prompt": "What is the weather like?", "unitID": "en-foundations-u2", "answers": ["Rainy"], "explain": "It is a rainy Monday.", "options": ["Rainy", "Sunny", "Snowy", "Windy and dry"], "section": "reading", "passageId": "en-listen-lost-umbrella"}, {"id": "en-listen-lost-umbrella-q3#r", "kind": "written", "prompt": "What colour is Marta's umbrella?", "unitID": "en-foundations-u2", "answers": ["green", "it is green", "her umbrella is green"], "explain": "Marta's umbrella is green.", "options": [], "section": "reading", "passageId": "en-listen-lost-umbrella"}, {"id": "en-listen-language-cafe-q2#l", "kind": "choice", "prompt": "Where is Lucas from?", "speech": "Every Wednesday evening, a small café in the city centre is a language café. Students from many countries sit together at big tables. Lucas is twenty-five years old, and he is from Brazil. His Portuguese and Spanish are excellent, and his English is quite good now. At his table there is a woman from Japan and two men from Italy. They ask simple questions: Where are you from? What do you do? Lucas is a nurse, and he is happy to answer. At ten o'clock the café closes, but the new friends are not tired. They are only happy to talk.", "unitID": "en-foundations-u1", "answers": ["Brazil"], "explain": "Lucas is from Brazil.", "options": ["Brazil", "Japan", "Italy", "Portugal"], "section": "listening", "passageId": "en-listen-language-cafe"}, {"id": "en-listen-language-cafe-q1#l", "kind": "choice", "prompt": "Where is the language café?", "speech": "Every Wednesday evening, a small café in the city centre is a language café. Students from many countries sit together at big tables. Lucas is twenty-five years old, and he is from Brazil. His Portuguese and Spanish are excellent, and his English is quite good now. At his table there is a woman from Japan and two men from Italy. They ask simple questions: Where are you from? What do you do? Lucas is a nurse, and he is happy to answer. At ten o'clock the café closes, but the new friends are not tired. They are only happy to talk.", "unitID": "en-foundations-u1", "answers": ["In a small café in the city centre"], "explain": "Every Wednesday evening, a small café in the city centre is a language café.", "options": ["In a small café in the city centre", "In a school", "In a park", "In a hotel"], "section": "listening", "passageId": "en-listen-language-cafe"}, {"id": "en-listen-rainy-day-q2#l", "kind": "choice", "prompt": "What is Ben doing?", "speech": "It is raining in Maple Street, and Anna is looking out of the window. Her brother Ben is playing a video game in the living room, and their mother is reading on the sofa. Outside, the neighbours are running to their cars with umbrellas. The cat is sleeping in its favourite chair, and the dog is watching the rain too. Anna is not bored — she is drawing the grey sky in her notebook. Her mother is making tea, and the kitchen smells wonderful. 'What are you doing?' Ben asks. 'I'm drawing the weather,' Anna says, 'because today the weather is interesting!'", "unitID": "en-foundations-now", "answers": ["He's playing a video game"], "explain": "Her brother Ben is playing a video game.", "options": ["He's playing a video game", "He's drawing", "He's making tea", "He's sleeping"], "section": "listening", "passageId": "en-listen-rainy-day"}, {"id": "en-listen-rainy-day-q1#l", "kind": "choice", "prompt": "What is the weather doing?", "speech": "It is raining in Maple Street, and Anna is looking out of the window. Her brother Ben is playing a video game in the living room, and their mother is reading on the sofa. Outside, the neighbours are running to their cars with umbrellas. The cat is sleeping in its favourite chair, and the dog is watching the rain too. Anna is not bored — she is drawing the grey sky in her notebook. Her mother is making tea, and the kitchen smells wonderful. 'What are you doing?' Ben asks. 'I'm drawing the weather,' Anna says, 'because today the weather is interesting!'", "unitID": "en-foundations-now", "answers": ["It's raining"], "explain": "It is raining in Maple Street.", "options": ["It's raining", "It's snowing", "It's sunny", "It's windy"], "section": "listening", "passageId": "en-listen-rainy-day"}, {"id": "en-foundations-friends-likes-e4", "kind": "written", "prompt": "Short answer: “Do you like cats?” (yes)", "unitID": "en-foundations-friends", "answers": ["yes i do", "yes, i do"], "explain": "Short answers repeat do.", "options": [], "section": "writing"}, {"id": "en-foundations-shopping-clothes-e4", "kind": "written", "prompt": "Ask for a size S.", "unitID": "en-foundations-shopping", "answers": ["do you have this in a small", "have you got this in a small"], "explain": "Do you have this in a small?", "options": [], "section": "writing"}, {"id": "en-foundations-home-problems-e4", "kind": "written", "prompt": "Di cuánto tiempo lleva el problema. (3 días)", "unitID": "en-foundations-home", "answers": ["its been like this for three days", "for three days"], "explain": "for + period.", "options": [], "section": "writing"}], "level": "A1", "weekId": 202642, "version": 1, "passages": [{"id": "en-listen-birthday-week", "text": "This is a special week for Leo. His birthday is on Friday, 12 September, and his family is planning three small parties. On Monday, his colleagues are taking him to a café after work. On Wednesday, his friends are coming to his flat for a film night — his sister is making her famous chocolate cake on Thursday, so the flat smells of chocolate for two days. The family party is on Saturday at three o'clock, at his grandparents' house. Leo's favourite day? 'Sunday,' he laughs, 'because then I can finally rest — my birthday week is wonderful but very busy!'", "title": "The birthday week"}, {"id": "en-listen-bus-stop-chat", "text": "It's cold at the bus stop, and Ben doesn't like silence. 'Cold today, isn't it?' he says to the woman next to him. 'Freezing,' she says. 'Any plans for the weekend?' Ben asks. 'Nothing much — you?' 'My sister is visiting, so we'll walk by the river if it doesn't rain.' The woman smiles. 'Sounds nice. My plans are tea and a book!' The bus arrives — late, of course. 'Have a good one!' Ben says as she gets on. 'You too!' And that's it: a complete conversation with a stranger, sixty seconds long.", "title": "The bus stop chat"}, {"id": "en-listen-busy-kitchen", "text": "It is Sunday morning, and the whole family is in the kitchen. Grandma is cutting bread, and Grandpa is making coffee — his coffee is always too strong. Anna's father is singing while he is cooking eggs, and her mother is setting the table. The twins are helping, but they are eating more strawberries than they are putting in the bowl. Even the dog is working: he is waiting under the table for pieces of cheese. 'Is anyone NOT eating in this kitchen?' Grandpa laughs. Everyone is smiling. Sunday breakfast is the family's favourite moment of the week.", "title": "Sunday in the kitchen"}, {"id": "en-listen-city-walk", "text": "Nadia is new in town, and today she explores on foot. In her street there is a small supermarket, a bakery and a bookshop — everything is very close, so she doesn't need the bus. She walks to the river and turns left. There, she can see the old bridge and a big park. In the park there are children, dogs and a lot of green space. She can't visit the museum because it is closed on Mondays, but she can sit in the sun. A man with a dog gives her directions to the market: \\"Go straight, cross the bridge, and the market is on your right.\\" She thanks him and walks on.", "title": "A walk in the new city"}, {"id": "en-listen-coffee-morning", "text": "Every morning, Marta walks to a small café near her flat. The waiter knows her name, so she never has to order. Today she sits by the window with a coffee and a croissant. Her bus leaves at half past eight, but she is not worried. The café is very quiet at this hour. She drinks her coffee slowly and watches the city wake up.", "title": "A coffee before work"}, {"id": "en-listen-language-cafe", "text": "Every Wednesday evening, a small café in the city centre is a language café. Students from many countries sit together at big tables. Lucas is twenty-five years old, and he is from Brazil. His Portuguese and Spanish are excellent, and his English is quite good now. At his table there is a woman from Japan and two men from Italy. They ask simple questions: Where are you from? What do you do? Lucas is a nurse, and he is happy to answer. At ten o'clock the café closes, but the new friends are not tired. They are only happy to talk.", "title": "The language café"}, {"id": "en-listen-lost-umbrella", "text": "It is a rainy Monday, and the classroom is full of umbrellas. \\"Whose umbrella is this?\\" the teacher asks. It is a big blue umbrella, and it is next to my chair. \\"It isn't mine,\\" says Marta. \\"My umbrella is green.\\" \\"Is it yours, Pedro?\\" \\"No, it isn't. My things are in my bag.\\" Then Daniel comes in, wet and tired. He looks at the blue umbrella and laughs. \\"That's my umbrella! It's my father's umbrella, and he needs it today.\\" The class laughs too. Daniel takes his umbrella, and the teacher writes on the board: your, my, his, her.", "title": "The blue umbrella"}, {"id": "en-listen-new-flatmate", "text": "Tom has got a new flatmate. His name is Leo and he is twenty-three years old. Leo comes from a small town in the north, but he works in the city now. He has got two boxes, a guitar and a bicycle. The flat has got two bedrooms and a sunny kitchen. Tom hopes Leo likes cooking, because Tom hates it.", "title": "A new flatmate"}, {"id": "en-listen-new-neighbour", "text": "There is a new neighbour in the building. Her name is Amélie, and she is from France. She is not a student; she is a photographer. She doesn't work in an office — she works at home, and she travels a lot. The people in the building are curious, but they are also shy, so they don't talk to her. Then one morning, Ben meets her at the door. \\"Are you the new neighbour?\\" he asks. \\"Yes, I am,\\" she says, \\"and I am happy to be here.\\" Now they are friends, and she isn't alone in the building.", "title": "The new neighbour"}, {"id": "en-listen-new-neighbourhood", "text": "Sofia just moved to Maple Street, and her new neighbour Tom is telling her everything. 'There's a bakery on the corner — the bread is fantastic. There are two schools, a park and a small library. There isn't a cinema, I'm afraid; the nearest one is two bus stops away.' Sofia asks about the park: 'Is there a chemist's near the park?' 'Yes, right next to it,' Tom says. 'And the people?' Sofia wants to know. 'They're friendly and very quiet,' Tom laughs, 'except on Saturdays, when the football starts.'", "title": "The new neighbourhood"}, {"id": "en-listen-night-shift", "text": "Paolo is a baker, and he works at night. His shift starts at eleven o'clock in the evening, and it finishes at seven in the morning. First, he makes the bread; then he makes the cakes. He never works alone — his cousin works with him, and they talk while they work. Paolo usually sleeps from nine in the morning to three in the afternoon. On Sundays he doesn't work, and he has lunch with his family. His neighbours sometimes ask him: \\"Do you like your job?\\" \\"Yes,\\" he says, \\"the city is quiet, the bread smells wonderful, and my mornings are free.\\"", "title": "The night shift"}, {"id": "en-listen-not-feeling-well", "text": "Daniel doesn't feel well this morning. He has got a headache and a sore throat, and his whole body is tired. At work, his colleague Sofia notices immediately. 'What's wrong?' she asks. 'I've got a cold, I think,' Daniel says. 'My throat hurts, and I can't stop sneezing.' Sofia is worried. 'Go home and rest! Drink hot tea with honey — my grandmother's recipe.' Daniel takes her advice. In the afternoon, he is in bed with a big cup of tea. His cat is sleeping next to him. On Friday he is back at work, and his colleagues say he looks great.", "title": "Not feeling well"}, {"id": "en-listen-rainy-day", "text": "It is raining in Maple Street, and Anna is looking out of the window. Her brother Ben is playing a video game in the living room, and their mother is reading on the sofa. Outside, the neighbours are running to their cars with umbrellas. The cat is sleeping in its favourite chair, and the dog is watching the rain too. Anna is not bored — she is drawing the grey sky in her notebook. Her mother is making tea, and the kitchen smells wonderful. 'What are you doing?' Ben asks. 'I'm drawing the weather,' Anna says, 'because today the weather is interesting!'", "title": "A rainy Saturday"}, {"id": "en-listen-saturday-list", "text": "Saturday morning, and Marta is at the supermarket with a long list. She needs bread, milk, eggs and tomatoes, but she can't find the tomatoes. A shop assistant is stacking apples nearby. 'Excuse me, where are the tomatoes?' Marta asks. 'Aisle three, next to the juice,' the assistant says. Marta finds them, checks the price — two euros fifty — and goes to the checkout. 'Anything else?' the cashier asks. 'No, that's all, thanks!' At home, she unpacks the bag and finds one thing missing: the bread. It's still on the kitchen table, next to her keys.", "title": "The Saturday list"}, {"id": "en-listen-sunday-market", "text": "On Sundays there is a market in the town square. Anna and her father go there at nine o'clock, before it gets busy. They buy fruit, bread and flowers. Anna wants some strawberries, but her father says they are too expensive this week. In the end they take home a big bag of oranges and some white roses for the kitchen table.", "title": "The Sunday market"}], "expiresAt": "2026-10-19T00:00:00Z", "languageID": "en", "thresholds": {"vocab": 60, "grammar": 60, "overall": 70, "reading": 50, "writing": 50, "listening": 50, "recognition": 60}, "schemaVersion": 1, "readingPassageIds": ["en-listen-lost-umbrella", "en-listen-bus-stop-chat"], "listeningPassageIds": ["en-listen-rainy-day", "en-listen-language-cafe"]}	2026-10-18 14:48:23.971664+00
