s-e1", "kind": "choice", "prompt": "Do you want ___ see a film?", "unitID": "en-foundations-friends", "answers": ["to"], "explain": "want to + verb.", "options": ["to", "for", "see", "seeing"], "section": "recognition"}, {"id": "en-foundations-u4-can-e3", "kind": "order", "prompt": "Say your mother cannot drive.", "unitID": "en-foundations-u4", "answers": ["She can't drive"], "explain": "can't + base verb: She can't drive.", "options": [], "section": "recognition"}, {"id": "checkpoint-en-a1-q2", "kind": "choice", "prompt": "___ she your sister?", "answers": ["Is"], "explain": "With she, questions start with Is.", "options": ["Is", "Are", "Am", "Does"], "section": "recognition"}, {"id": "checkpoint-en-a1-q15", "kind": "choice", "prompt": "You are in a café. How do you order politely?", "answers": ["Can I have a coffee, please?"], "explain": "Can I have …, please? is the polite order.", "options": ["Can I have a coffee, please?", "Give me coffee.", "Coffee now.", "You want coffee?"], "section": "recognition"}, {"id": "checkpoint-en-a1-q6", "kind": "gap", "prompt": "She ___ football on Saturdays. (play)", "answers": ["plays"], "explain": "Third person -s: she plays.", "options": [], "section": "recognition"}, {"id": "en-listen-language-cafe-q3#r", "kind": "written", "prompt": "How old is Lucas?", "unitID": "en-foundations-u1", "answers": ["twenty-five", "25", "he is twenty-five"], "explain": "Lucas is twenty-five years old.", "options": [], "section": "reading", "passageId": "en-listen-language-cafe"}, {"id": "en-listen-language-cafe-q2#r", "kind": "choice", "prompt": "Where is Lucas from?", "unitID": "en-foundations-u1", "answers": ["Brazil"], "explain": "Lucas is from Brazil.", "options": ["Brazil", "Japan", "Italy", "Portugal"], "section": "reading", "passageId": "en-listen-language-cafe"}, {"id": "en-listen-language-cafe-q1#r", "kind": "choice", "prompt": "Where is the language café?", "unitID": "en-foundations-u1", "answers": ["In a small café in the city centre"], "explain": "Every Wednesday evening, a small café in the city centre is a language café.", "options": ["In a small café in the city centre", "In a school", "In a park", "In a hotel"], "section": "reading", "passageId": "en-listen-language-cafe"}, {"id": "en-listen-not-feeling-well-q2#r", "kind": "written", "prompt": "What has Daniel got?", "unitID": "en-foundations-days", "answers": ["a cold", "he has got a cold", "he's got a cold", "a headache and a cold"], "explain": "He thinks he has got a cold.", "options": [], "section": "reading", "passageId": "en-listen-not-feeling-well"}, {"id": "en-listen-not-feeling-well-q1#r", "kind": "choice", "prompt": "How does Daniel feel this morning?", "unitID": "en-foundations-days", "answers": ["He doesn't feel well"], "explain": "Daniel doesn't feel well this morning.", "options": ["He doesn't feel well", "He feels great", "He is angry", "He is hungry"], "section": "reading", "passageId": "en-listen-not-feeling-well"}, {"id": "en-listen-not-feeling-well-q3#r", "kind": "choice", "prompt": "Who notices first?", "unitID": "en-foundations-days", "answers": ["His colleague Sofia"], "explain": "His colleague Sofia notices immediately.", "options": ["His colleague Sofia", "His mother", "His cat", "His boss"], "section": "reading", "passageId": "en-listen-not-feeling-well"}, {"id": "en-listen-coffee-morning-q1#l", "kind": "choice", "prompt": "Where does Marta go every morning?", "speech": "Every morning, Marta walks to a small café near her flat. The waiter knows her name, so she never has to order. Today she sits by the window with a coffee and a croissant. Her bus leaves at half past eight, but she is not worried. The café is very quiet at this hour. She drinks her coffee slowly and watches the city wake up.", "unitID": "en-foundations-u3", "answers": ["To a small café"], "explain": "She walks to a small café near her flat.", "options": ["To a small café", "To her office", "To the bus station", "To a park"], "section": "listening", "passageId": "en-listen-coffee-morning"}, {"id": "en-listen-coffee-morning-q2#l", "kind": "choice", "prompt": "What does she have for breakfast today?", "speech": "Every morning, Marta walks to a small café near her flat. The waiter knows her name, so she never has to order. Today she sits by the window with a coffee and a croissant. Her bus leaves at half past eight, but she is not worried. The café is very quiet at this hour. She drinks her coffee slowly and watches the city wake up.", "unitID": "en-foundations-u3", "answers": ["A coffee and a croissant"], "explain": "She sits by the window with a coffee and a croissant.", "options": ["Tea and toast", "A coffee and a croissant", "Orange juice", "Nothing"], "section": "listening", "passageId": "en-listen-coffee-morning"}, {"id": "en-listen-rainy-day-q2#l", "kind": "choice", "prompt": "What is Ben doing?", "speech": "It is raining in Maple Street, and Anna is looking out of the window. Her brother Ben is playing a video game in the living room, and their mother is reading on the sofa. Outside, the neighbours are running to their cars with umbrellas. The cat is sleeping in its favourite chair, and the dog is watching the rain too. Anna is not bored — she is drawing the grey sky in her notebook. Her mother is making tea, and the kitchen smells wonderful. 'What are you doing?' Ben asks. 'I'm drawing the weather,' Anna says, 'because today the weather is interesting!'", "unitID": "en-foundations-now", "answers": ["He's playing a video game"], "explain": "Her brother Ben is playing a video game.", "options": ["He's playing a video game", "He's drawing", "He's making tea", "He's sleeping"], "section": "listening", "passageId": "en-listen-rainy-day"}, {"id": "en-listen-rainy-day-q1#l", "kind": "choice", "prompt": "What is the weather doing?", "speech": "It is raining in Maple Street, and Anna is looking out of the window. Her brother Ben is playing a video game in the living room, and their mother is reading on the sofa. Ou